const { statusCode, body } = $input.first().json;
if (statusCode !== 200 || !Array.isArray(body?.data)) throw new Error('Expected HTTP 200 with a model catalog.');
const models = body.data.filter(m => m.input_modalities?.includes('text') && m.output_modalities?.includes('text')).map(m => ({ id: m.id, tools: m.supported_features?.includes('tools') ?? false }));
if (!models.length) throw new Error('No text models found in the catalog.');
return [{ json: { passed: true, statusCode, count: models.length, models } }];
